contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address keeper, bool approve, address logger) public {
        require(logger != address(this));
        bool r1 = c.logCreated(keeper);
        c.setApprovedLogger(logger, approve);
        bool approvedNow = c.approvedToLog(logger);
        // msg.sender of logCreated calls is this contract, not logger
        bool r2;
        if (approve && logger == address(this)) {
            r2 = c.logCreated(keeper);
            assert(r1 == false && r2 == true && approvedNow);
        } else {
            r2 = c.logCreated(keeper);
            assert(r1 == false && r2 == false && !approvedNow);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address keeper) public {
        bool before = c.approvedToLog(address(this));
        c.setApprovedLogger(address(this), true);
        bool approvedNow = c.approvedToLog(address(this));
        bool r = c.logCreated(keeper);
        assert(before == false && approvedNow == true && r == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        bool approvedBefore = c.approvedToLog(address(this));
        require(approvedBefore == false);
        bool r = c.logFunded();
        bool approvedAfter = c.approvedToLog(address(this));
        assert(r == false && approvedAfter == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger, bool status, bytes32 digest) public {
        bool before = c.approvedToLog(logger);
        c.setApprovedLogger(logger, status);
        bool after = c.approvedToLog(logger);
        // logCourtesyCalled is called from this contract, so observe its return value
        bool r = c.logCourtesyCalled();
        assert(after == status && r == status && before != after || after == status && r == status);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger, bool status, bytes32 digest) public {
        bool before = c.approvedToLog(logger);
        c.setApprovedLogger(logger, status);
        bool after_ = c.approvedToLog(logger);
        bool r = c.logCourtesyCalled();
        assert(after_ == status && r == status && (before != after_ || !status));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger) public {
        require(logger != address(this));
        bool initiallyApproved = c.approvedToLog(logger);
        bool r1 = c.logFunded();
        bool r2 = c.logRedeemed(bytes32(uint256(1)));
        assert(!initiallyApproved && !r1 && !r2);
    }
    receive() external payable {}
}
